#include "processor_windows.hpp"
#include "processor_state.hpp"
#include <iostream>
#include <limits>
#include <stdexcept>

namespace os=syspane::platform;namespace r=syspane::runtime;using C=os::ProcessorReadCode;
using Bytes=std::vector<unsigned char>;
void need(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
void put(Bytes& bytes,std::size_t at,std::uint64_t n,std::size_t width){for(std::size_t i=0;i<width;++i)bytes.at(at+i)=static_cast<unsigned char>(n>>(i*8));}
Bytes groups(const std::vector<std::uint64_t>& masks){Bytes bytes(32+masks.size()*48);put(bytes,0,4,4);put(bytes,4,bytes.size(),4);put(bytes,8,masks.size(),2);put(bytes,10,masks.size(),2);for(std::size_t i=0;i<masks.size();++i){put(bytes,32+i*48,64,1);auto value=masks[i];unsigned count=0;while(value){value&=value-1;++count;}put(bytes,33+i*48,count,1);put(bytes,72+i*48,masks[i],8);}return bytes;}
Bytes relations(unsigned kind,const std::vector<std::vector<os::WindowsAffinity>>& sets){Bytes bytes;for(const auto& masks:sets){const auto at=bytes.size(),size=32+masks.size()*16;bytes.resize(at+size);put(bytes,at,kind,4);put(bytes,at+4,size,4);put(bytes,at+30,masks.size(),2);for(std::size_t i=0;i<masks.size();++i){put(bytes,at+32+i*16,masks[i].mask,8);put(bytes,at+40+i*16,masks[i].group,2);}}return bytes;}
os::WindowsTopology fixture(){auto result=os::decode_windows_topology(groups({1,std::uint64_t{1}<<31}),relations(0,{{{1,std::uint64_t{1}<<31}},{{0,1}}}),relations(3,{{{0,1},{1,std::uint64_t{1}<<31}}}));need(result.code==C::success,"valid sparse topology");return result.value;}
os::WindowsProcessorRow row(std::uint16_t group,std::uint8_t number,std::int64_t idle,std::int64_t total){return {group,number,{{{0,0,0x20510500,1,total-idle,10000,42},{0,0,0x20510500,1,0,10000,42},{0,0,0x20510500,1,idle,10000,42}}}};}
syspane::model::Tick tick(std::uint64_t ns){return {"epoch:windows",ns,"clock:1","scope:1"};}
r::ProcessorState owner(){return r::ProcessorState("epoch:windows","clock:1","scope:1","windows:pdh-accounted-time-v1");}
void topology(){auto value=fixture();need(value.groups.size()==2&&value.groups[1].mask==(std::uint64_t{1}<<31)&&value.cores.size()==2&&value.packages.size()==1,"all sparse groups and canonical relationships");auto reordered=os::decode_windows_topology(groups({1,std::uint64_t{1}<<31}),relations(0,{{{0,1}},{{1,std::uint64_t{1}<<31}}}),relations(3,{{{1,std::uint64_t{1}<<31},{0,1}}}));need(reordered.code==C::success&&reordered.value==value,"relationship ordering not identity");auto data=os::decode_windows_processors(value,value,{row(1,31,50,200),row(0,0,60,100)});need(data.code==C::success&&data.rows[0].group==0&&data.counters().rows[1].id=="windows:cpu:1:31","complete sorted IDs independent from enumeration");auto changed=value;changed.cores[0].efficiency=2;need(os::decode_windows_processors(value,changed,data.rows).code==C::interrupted,"reported topology change interrupted");}
void intervals(){auto topology=fixture();auto state=owner();state.demand(1);auto first=os::decode_windows_processors(topology,topology,{row(0,0,60,100),row(1,31,50,200)});need(state.commit(1,0,first.counters(),tick(100),tick(110))==r::ProcessorStateCode::accepted,"first accepted");need(!state.sample()->aggregate&&state.sample()->pending==r::ProcessorPending::first,"first pending");auto second=os::decode_windows_processors(topology,topology,{row(1,31,70,300),row(0,0,80,160)});need(state.commit(1,0,second.counters(),tick(200),tick(205))==r::ProcessorStateCode::accepted,"second accepted");const auto sample=state.sample();need(sample->aggregate->busy==120&&sample->aggregate->total==160&&sample->aggregate->interval_ns==100&&sample->aggregate->percent()==75,"literal accounted-time weighted ratio and start interval");need(sample->domains.at("windows:group:0").busy==40&&sample->domains.at("windows:group:1").total==100,"each real group contributes");}
void complete(){const auto full=std::numeric_limits<std::uint64_t>::max();std::vector<std::vector<os::WindowsAffinity>> cores;std::vector<os::WindowsProcessorRow> a,b;for(unsigned group=0;group<2;++group)for(unsigned bit=0;bit<64;++bit){cores.push_back({{static_cast<std::uint16_t>(group),std::uint64_t{1}<<bit}});a.push_back(row(static_cast<std::uint16_t>(group),static_cast<std::uint8_t>(bit),50,100));b.push_back(row(static_cast<std::uint16_t>(group),static_cast<std::uint8_t>(bit),100,200));}auto decoded=os::decode_windows_topology(groups({full,full}),relations(0,cores),relations(3,{{{0,full}},{{1,full}}}));need(decoded.code==C::success&&decoded.value.cores.size()==128,"all 128 CPUs with bit63 in both groups");auto state=owner();state.demand(1);auto first=os::decode_windows_processors(decoded.value,decoded.value,a);auto second=os::decode_windows_processors(decoded.value,decoded.value,b);state.commit(1,0,first.counters(),tick(100),tick(100));state.commit(1,0,second.counters(),tick(200),tick(200));need(state.sample()->processors.size()==128&&state.sample()->domains.size()==2&&state.sample()->aggregate->busy==6400&&state.sample()->aggregate->total==12800,"complete group aggregate without selecting one mask or averaging");need(os::decode_windows_processors(decoded.value,decoded.value,b,127).code==C::capacity,"smaller budget never truncates");auto omitted=b;omitted.resize(64);need(os::decode_windows_processors(decoded.value,decoded.value,omitted).code==C::malformed,"omitted whole group never qualifies a complete batch");}
void malformed(){auto group=groups({1});auto core=relations(0,{{{0,1}}});auto package=relations(3,{{{0,1}}});auto expect=[&](const Bytes& g,const Bytes& c,const Bytes& p,C code=C::malformed){auto result=os::decode_windows_topology(g,c,p);need(result.code==code&&result.value.groups.empty(),"malformed topology is atomic");};auto bad=group;bad.pop_back();expect(bad,core,package);bad=group;put(bad,4,0,4);expect(bad,core,package);bad=group;put(bad,33,2,1);expect(bad,core,package);bad=group;put(bad,32,0,1);expect(bad,core,package);bad=group;put(bad,32,1,1);put(bad,72,2,8);expect(bad,core,package);bad=group;bad.push_back(0);expect(bad,core,package);expect(group,{},package);expect(group,relations(3,{{{0,1}}}),package);expect(group,relations(0,{{{1,1}}}),package);expect(group,relations(0,{{{0,1}},{{0,1}}}),package);expect(group,core,relations(3,{{{0,1}},{{0,1}}}));expect(groups({3}),relations(0,{{{0,3}}}),relations(3,{{{0,1}},{{0,2}}}));expect(group,relations(0,{{{0,1},{0,1}}}),package);bad=group;bad.resize(8388609);expect(bad,core,package,C::capacity);auto result=os::decode_windows_topology(group,core,package,0);need(result.code==C::capacity,"zero budget");}
void statuses(){auto topology=fixture();const auto good=std::vector<os::WindowsProcessorRow>{row(0,0,60,100),row(1,31,50,200)};for(auto status:{std::uint32_t{0},std::uint32_t{1}}){auto rows=good;rows[0].accounting[0].counter_status=status;need(os::decode_windows_processors(topology,topology,rows).code==C::success,"valid and new data accepted");}for(auto error:{std::uint32_t{5},std::uint32_t{0xc0000bdb},std::uint32_t{0xc0000bbb},std::uint32_t{0xc0000bb8},std::uint32_t{0x800007d1}}){auto rows=good;rows[1].accounting[0].counter_status=error;auto decoded=os::decode_windows_processors(topology,topology,rows);need(decoded.code==os::windows_processor_error(error)&&decoded.native_error==error&&decoded.rows.empty(),"raw status failure not successful zero");rows=good;rows[0].accounting[0].api_status=error;decoded=os::decode_windows_processors(topology,topology,rows);need(decoded.code==os::windows_processor_error(error)&&decoded.rows.empty(),"API and data statuses separate");}auto bad=good;bad[0].accounting[0].counter_type=0;need(os::decode_windows_processors(topology,topology,bad).code==C::unsupported,"unknown type not guessed");for(int kind=0;kind<4;++kind){bad=good;if(kind==0)bad[0].accounting[0].first=-1;if(kind==1)bad[0].accounting[0].second=0;if(kind==2)bad[0].accounting[0].first=10001;if(kind==3)bad[0].accounting[0].multi_count=2;need(os::decode_windows_processors(topology,topology,bad).code==C::malformed,"invalid raw shape");}bad=good;bad[0].accounting[1].timestamp=43;need(os::decode_windows_processors(topology,topology,bad).code==C::interrupted,"incoherent component timestamps");bad=good;for(auto& part:bad[0].accounting){part.first=std::numeric_limits<std::int64_t>::max();part.second=part.first;}need(os::decode_windows_processors(topology,topology,bad).code==C::capacity,"checked accounted sum overflow");bad=good;bad.pop_back();need(os::decode_windows_processors(topology,topology,bad).code==C::malformed,"missing CPU");bad=good;bad[1]=bad[0];need(os::decode_windows_processors(topology,topology,bad).code==C::malformed,"duplicate CPU");}
void recovery(){auto topology=fixture();auto state=owner();state.demand(1);auto commit=[&](std::int64_t idle,std::int64_t total,std::uint64_t ns){auto result=os::decode_windows_processors(topology,topology,{row(0,0,idle,total),row(1,31,idle,total)});return state.commit(1,0,result.counters(),tick(ns),tick(ns));};commit(0,1,100);commit(100,101,200);need(state.sample()->aggregate->busy==0&&state.sample()->aggregate->percent()==0,"real zero");commit(100,201,300);need(state.sample()->aggregate->percent()==100,"full CPU interval");state.commit(1,0,{C::failed,7},tick(400),tick(400));commit(110,251,500);need(!state.sample()->aggregate&&state.sample()->pending==r::ProcessorPending::acquisition_gap,"failed interval never bridged");commit(120,301,600);need(state.sample()->aggregate->busy==80&&state.sample()->aggregate->total==100,"recovered basis");commit(1,2,700);need(state.sample()->pending==r::ProcessorPending::counter_reset,"counter decrease rebase");commit(2,2,800);need(state.sample()->pending==r::ProcessorPending::counter_reset,"individual accounting decrease cannot hide in a nondecreasing sum");r::ProcessorState rejected("epoch:windows","clock:1","scope:1","windows:rejected-inverse-timer");rejected.demand(1);
const os::ProcessorResult rejected_before{C::success,0,{{"cpu:3","group:0",100000000,1000000,{}}}};
const os::ProcessorResult rejected_after{C::success,0,{{"cpu:3","group:0",110700031,11781250,{}}}};
const auto rejected_begin=tick(100),rejected_end=tick(200);
need(rejected.commit(1,0,rejected_before,rejected_begin,rejected_begin)==r::ProcessorStateCode::accepted,"rejected candidate basis");
need(rejected.commit(1,0,rejected_after,rejected_end,rejected_end)==r::ProcessorStateCode::invalid&&!rejected.current(),"original native idle 10781250 exceeds denominator 10700031 and is never clamped");
std::atomic_bool cancel{true};os::ProcessorRequest request{std::chrono::steady_clock::now()+std::chrono::seconds(1),cancel};need(os::processor_stopped(request)==C::cancelled,"cancel contract");cancel=false;request.deadline=std::chrono::steady_clock::now()-std::chrono::seconds(1);need(os::processor_stopped(request)==C::timed_out,"timeout contract");}
int main(int argc,char** argv){try{need(argc==2,"case required");const std::string name=argv[1];if(name=="TOPOLOGY")topology();else if(name=="INTERVALS")intervals();else if(name=="COMPLETE")complete();else if(name=="MALFORMED")malformed();else if(name=="STATUSES")statuses();else if(name=="RECOVERY")recovery();else throw std::runtime_error("unknown Windows processor case");std::cout<<name<<": pass\n";return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
